import json

_counter = {"id": "1", "value": 0}


def _normalize(path):
    if path is None:
        return "/"
    p = path.split("?", 1)[0]
    if not p.startswith("/"):
        p = "/" + p
    if len(p) > 1 and p.endswith("/"):
        p = p.rstrip("/")
        if not p:
            p = "/"
    return p


def handle(method, path, body):
    p = _normalize(path)
    m = (method or "").upper()

    if p == "/counter":
        if m == "GET":
            return 200, {"id": _counter["id"], "value": _counter["value"]}
        return 405, {"error": "不支援的請求方法"}

    if p == "/counter/increment":
        if m == "POST":
            _counter["value"] += 1
            return 200, {"id": _counter["id"], "value": _counter["value"]}
        return 405, {"error": "不支援的請求方法"}

    return 404, {"error": "找不到路徑"}

