(function () {
  var display = document.getElementById('counter-display');
  var button = document.getElementById('increment-button');
  var errorBox = document.getElementById('error-message');

  function showError(message) {
    errorBox.textContent = message;
    errorBox.hidden = false;
  }

  function clearError() {
    errorBox.textContent = '';
    errorBox.hidden = true;
  }

  function showValue(data) {
    if (data && typeof data.value !== 'undefined') {
      display.textContent = String(data.value);
    } else {
      throw new Error('伺服器回傳的資料格式不正確');
    }
  }

  async function call(path, options) {
    var response;
    try {
      response = await fetch(path, options);
    } catch (e) {
      throw new Error('無法連線到伺服器，請稍後再試');
    }
    var data = null;
    try {
      data = await response.json();
    } catch (e) {
      data = null;
    }
    if (!response.ok) {
      var msg = data && data.error ? data.error : '伺服器發生錯誤（狀態碼 ' + response.status + '）';
      throw new Error(msg);
    }
    return data;
  }

  async function loadCounter() {
    clearError();
    try {
      var data = await call('api/counter', { method: 'GET' });
      showValue(data);
    } catch (e) {
      showError('讀取失敗：' + e.message);
    }
  }

  async function increment() {
    clearError();
    button.disabled = true;
    try {
      var data = await call('api/counter/increment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({})
      });
      showValue(data);
    } catch (e) {
      showError('加一失敗：' + e.message);
    } finally {
      button.disabled = false;
    }
  }

  button.addEventListener('click', increment);
  document.addEventListener('DOMContentLoaded', loadCounter);
  if (document.readyState !== 'loading') {
    loadCounter();
  }
})();

